{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Nitrofurantoin itself was reported to have approximately 90% oral bioavailability in humans; the query is nitrofurantoin, providing direct evidence for F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Absolute bioavailability estimates in humans, based on urinary recovery after intravenous and intramuscular administration, indicate essentially complete absorption of nitrofurantoin from tablet and capsule formulations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Benznidazole, a related nitroheterocycle, has extensive oral bioavailability >90%, supporting high oral absorption for this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "5-Nitroimidazoles are almost completely and promptly absorbed after oral tablet administration, with bioavailability >90%, supporting high oral bioavailability for nitroheterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Niridazole has low systemic availability due to high hepatic extraction, but this reflects a different nitrothiazole scaffold with prominent first-pass metabolism and is outweighed by direct nitrofurantoin data.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is nitrofurantoin. Direct human evidence reports approximately 90% oral bioavailability and essentially complete absorption, far above the 20% threshold. Related nitroheterocycles also show high oral bioavailability. The few low-bioavailability nitroheterocycles are structurally and mechanistically distinct and do not override the direct evidence.",
  "evidence_gaps": [
    "No conflicting high-quality absolute bioavailability measurement for nitrofurantoin itself was retrieved.",
    "Mechanistic first-pass metabolism data for the exact query are not detailed, but direct human absorption estimates are sufficient for the threshold decision."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

